import sys

def main():
    data = sys.stdin.read().split()
    if len(data) < 16:
        return
    points = []
    for i in range(8):
        a = int(data[2 * i])
        b = int(data[2 * i + 1])
        points.append((a, b))
    points.sort(key=lambda p: p[0])

    if not (points[0][0] == points[1][0] == points[2][0]):
        print("ugly")
        return
    if not (points[5][0] == points[6][0] == points[7][0]):
        print("ugly")
        return
    if not (points[3][0] == points[4][0]):
        print("ugly")
        return
    if points[0][0] == points[7][0]:
        print("ugly")
        return
    if points[0][0] == points[3][0]:
        print("ugly")
        return

    b0, b1, b2 = points[0][1], points[1][1], points[2][1]
    if b0 == b1 or b0 == b2 or b1 == b2:
        print("ugly")
        return

    last_three_b = [points[5][1], points[6][1], points[7][1]]
    min_b = min(last_three_b)
    max_b = max(last_three_b)
    first_three_b = {b0, b1, b2}
    for b in last_three_b:
        if b not in first_three_b:
            print("ugly")
            return

    if last_three_b[0] == last_three_b[1] or last_three_b[0] == last_three_b[2] or last_three_b[1] == last_three_b[2]:
        print("ugly")
        return

    b3, b4 = points[3][1], points[4][1]
    if not (b3 == min_b or b3 == max_b):
        print("ugly")
        return
    if not (b4 == min_b or b4 == max_b):
        print("ugly")
        return
    if b3 == b4:
        print("ugly")
        return

    print("respectable")

if __name__ == "__main__":
    main()

